import{c as a,Q as r,j as t,m as i}from"./chunks/framework.BXc4yaFE.js";const c=JSON.parse('{"title":"Memory in the LLM Era: Modular Architectures and Strategies in a Unified Framework","description":"","frontmatter":{"url":"https://arxiv.org/abs/2604.01707","title":"Memory in the LLM Era: Modular Architectures and Strategies in a Unified Framework","archived_date":"2026-06-24T00:00:00.000Z","arxiv_id":2604.01707,"authors":["Yanchen Wu","Tenghui Lin","Yingli Zhou","Fangyuan Zhang","Qintian Guo","Xun Zhou","Sibo Wang","Xilin Liu","Yuchi Ma","Yixiang Fang"],"domains":["cs.CL"],"html":"https://arxiv.org/html/2604.01707v1","pdf_path":"pdfs/2604.01707.pdf","published_date":"2026-04-01T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-04-01-memory-llm-era-modular-architectures-2604-01707.md","filePath":"research/papers/2026-04-01-memory-llm-era-modular-architectures-2604-01707.md","lastUpdated":1785909234000}'),o={name:"research/papers/2026-04-01-memory-llm-era-modular-architectures-2604-01707.md"};function n(s,e,l,h,d,m){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="memory-in-the-llm-era-modular-architectures-and-strategies-in-a-unified-framework" tabindex="-1">Memory in the LLM Era: Modular Architectures and Strategies in a Unified Framework <a class="header-anchor" href="#memory-in-the-llm-era-modular-architectures-and-strategies-in-a-unified-framework" aria-label="Permalink to &quot;Memory in the LLM Era: Modular Architectures and Strategies in a Unified Framework&quot;">​</a></h1><p><strong>Authors</strong>: Yanchen Wu, Tenghui Lin, Yingli Zhou, Fangyuan Zhang, Qintian Guo, Xun Zhou, Sibo Wang, Xilin Liu, Yuchi Ma, Yixiang Fang <strong>Published</strong>: April 01, 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2604.01707" target="_blank" rel="noreferrer">https://arxiv.org/abs/2604.01707</a> · <a href="https://arxiv.org/html/2604.01707v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2604.01707 <strong>Categories</strong>: cs.CL <strong>PDF</strong>: <a href="https://arxiv.org/abs/2604.01707" target="_blank" rel="noreferrer">research/papers/pdfs/2604.01707.pdf</a> (20 pp, full text archived)</p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>Memory emerges as the core module in the large language model (LLM)-based agents for long-horizon complex tasks (e.g., multi-turn dialogue, game playing, scientific discovery), where memory can enable knowledge accumulation, iterative reasoning and self-evolution. A number of memory methods have been proposed in the literature. However, these methods have not been systematically and comprehensively compared under the same experimental settings. In this paper, we first summarize a unified framework that incorporates all the existing agent memory methods from a high-level perspective. We then extensively compare representative agent memory methods on two well-known benchmarks and examine the effectiveness of all methods, providing a thorough analysis of those methods. As a byproduct of our experimental analysis, we also design a new memory method by exploiting modules in the existing methods, which outperforms the state-of-the-art methods. Finally, based on these findings, we offer promising future research opportunities. We believe that a deeper understanding of the behavior of existing methods can provide valuable new insights for future research.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><ul><li>提出一個高層次 unified framework，將既有 agent memory 方法統合納入同一視角。</li><li>在相同實驗設定下，對代表性方法於兩個知名 benchmark 做系統性、全面比較（補足過往「設定不一致無法公平比較」的缺口）。</li><li>作為分析副產物，藉組合既有方法的模組設計出一個新記憶方法，超越 SOTA。</li></ul><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li>統一設定下的對照揭示各方法有效性差異；組合式新方法 outperform state-of-the-art（abstract 未列具體數字）。</li><li>提出未來研究方向清單。</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><ul><li>文件未於 abstract 列明確 limitation；判斷弱點：survey + 實驗綜合論文，新方法的增益幅度未在 abstract 量化；僅兩 benchmark，外部效度待補。</li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li>「同設定下公平比較」呼應 core.md TEST 的 unverified_success 閘門與 <code>core.md §PROPOSE 委派</code>（原 subagent-strategy.md）「verdict 非證據，須機械重驗」——記憶方法宣稱的增益須在受控設定下重驗。</li><li>unified framework 的「模組化拆解」對應本批多篇（LightMem/HyMem）共同的 retrieval/write/consolidate 分層，可作為比較記憶設計時的共同詞彙。</li><li>⚠️ 落地門檻：屬學術 benchmark 對照研究，與本庫 markdown 記憶層無直接映射；價值在提供「記憶方法分類」的概念地圖。</li></ul>',16)])])}const g=a(o,[["render",n]]);export{c as __pageData,g as default};
